  G.groups.forEach(g=>{ if(!g.violent||!g.n||g.k==='A'||g.k==='B') return; if(G.t-(g.bt||g.vt)>75&&G.barr.length<6){ const c=across(g.cx+(R()-.5)*12,g.cy+(R()-.5)*12,9); if(free0(c.x,c.y)){ g.bt=G.t; G.barr.push({x:c.x,y:c.y,ang:c.ang,len:c.len}); G.st.dmg++; G.dirty=true; lg(gName(g)+L(' levanta una barricada con contenedores ',' builds a barricade of rubbish containers ')+nearName(c.x,c.y),'bad'); radio('barricada',c.x,c.y,g); } } });
  { const A=G.groups.find(g=>g.k==='A'), B=G.groups.find(g=>g.k==='B'); if(A&&B&&A.n&&B.n&&!G.apr&&A.state==='seek'&&Math.hypot(A.cx-B.cx,A.cy-B.cy)<150){ G.apr=1; radio('acercan',(A.cx+B.cx)/2,(A.cy+B.cy)/2); } }
  if(FAC()) G.units.forEach(u=>{ /* Fácil: los grupos se defienden solos y protegen los furgones cercanos (solo frente a violentos armados) */
    if(u.out||u.st==='charge'||u.st==='move'||u.st==='detain'||G.t<(u.adT||0)) return; const tg=[]; const isV=a=>{ const g=G.groups[a.g]; return !(a.fl>G.t)&&((g.violent&&a.arm)||((g.k==='A'||g.k==='B')&&g.state==='seek')); };
    eachNear(u.x,u.y,u.big?16:9,a=>{ if(isV(a)) tg.push(a); });
    G.vans.forEach(v=>{ if(!v.on||Math.hypot(v.x-u.x,v.y-u.y)>40) return; eachNear(v.x,v.y,11,a=>{ if(isV(a)&&tg.indexOf(a)<0) tg.push(a); }); });
    if(tg.length<2) return; u.adT=G.t+18; let det=0; tg.forEach(a=>{ a.fl=G.t+25+a.r*15; if(a.arm&&a.on&&dacc('ad'+u.nm,0.06)){ a.on=0; det++; G.st.det++; G.st.detV++; } }); const g=G.groups[tg[0].g]; g.T=Math.max(0,g.T-4); G.lastAct=G.t; inc('autodef');
    fxt(u.x,u.y,'Se defiende','Self-defence','#9fd0ff'); lg(u.nm+L(' se defiende y repele a los violentos ',' defends itself and pushes back the violent ones ')+nearName(u.x,u.y)+(det?L(' ('+det+' detenido'+(det>1?'s':'')+')',' ('+det+' arrested)'):''),'good'); });
  perceive(); radioPump();
  /* peleas entre grupos rivales */
  let fight=false; G.fc=0; G.ag.forEach(a=>{ if(!a.on) return; const g=G.groups[a.g]; if(g.k!=='A'||!g.foe) return; eachNear(a.x,a.y,2.2,(b)=>{ if(b.g===g.foe.id){ fight=true; G.fc=(G.fc||0)+1; } }); });
  if(fight){ if(dacc('fi',Math.min(0.15,G.fc*0.002))) G.st.civ++; G.st.fightS++; G.groups.forEach(g=>{ if((g.k==='A'||g.k==='B')&&g.state==='seek'){ g.fs=(g.fs||0)+1; if(g.fs>100+R()*60){ g.state='leave'; lg(gName(g)+L(' se dispersa tras la pelea',' scatters after the brawl'),''); } } }); G.groups.forEach(g=>{ if(g.k==='A'||g.k==='B') g.T=Math.min(100,g.T+0.6); }); if(!G.fightLog||G.t-G.fightLog>90){ G.fightLog=G.t; lg(L('¡Los dos grupos llegan a las manos ','The two groups come to blows ')+nearName(G.groups[0].cx,G.groups[0].cy)+'!','bad'); } }
