function ustate(u){ if(u.van) return u.mv?L('circulando','driving'):u.on?L('cruzado, corta la calle','parked across, street blocked'):L('aparcado a un lado','parked aside'); return {hold:L('en línea','holding the line'),move:L('moviéndose','moving'),charge:L('cargando','charging'),detain:L('deteniendo','arresting'),aside:L('apartado, sin cortar la calle','standing aside, street open')}[u.st]||u.st; }
function shareURL(){ const c=G?G.cfg:CFG; return location.origin+location.pathname+'#/antidisturbios?m='+c.m+'&e='+c.e+'&h='+c.h+'&g='+c.g+'&s='+c.s+(c.d==='r'?'&d=r':''); }
function page(inner){ X.set('<div class="ad" data-noi18n>'+X.crumbs([[L('Inicio','Home'),'#/'],[L('Juegos','Games'),'#/juegos'],[L('Antidisturbios','Riot control')]])+'<h1>'+L('Antidisturbios','Riot control')+'</h1><p class="sub">'+L('Simulador de gestión del orden público: diriges a la UIP de la Policía Nacional en calles reales de Madrid. Cada decisión tiene consecuencias.','Public-order management simulator: you command the National Police UIP on real Madrid streets. Every decision has consequences.')+'</p><div id="ad-main">'+inner+'</div>'+datosHTML()+'</div>',L('Antidisturbios','Riot control')); }
function seg(k,opts){ return '<div class="ad-seg" role="group">'+opts.map(o=>'<button type="button" data-set="'+k+'" data-v="'+o[0]+'" class="'+(String(CFG[k])===String(o[0])?'on':'')+'">'+o[1]+'</button>').join('')+'</div>'; }
function setupHTML(){ const g=CFG.g, b=budgetFor(g,CFG.d), fac=CFG.d!=='r';
  return '<div class="ad-set">'+'<div class="ad-row"><span class="ad-lb">'+L('Misiones especiales','Special missions')+'</span><div class="mi-cards" style="display:grid;gap:8px">'+[['mi-bus',L('Escolta del autobús del equipo','Team bus escort'),L('UIP y Caballería llevan el autobús del equipo local por la Castellana hasta el estadio Santiago Bernabéu: calzada despejada, nadie delante y ningún objeto contra él.','UIP and mounted police take the home team bus along the Castellana to the Santiago Bernabéu stadium: road clear, no one in front, nothing thrown at it.')],['mi-vis',L('Visita oficial','Official visit'),L('Llega una alta autoridad a la Plaza Mayor: la UIP en cada entrada con controles de acceso, detector y cacheos, sin colas eternas.','A dignitary arrives at the Plaza Mayor: UIP at every entrance with access checks, detector and pat-downs, without endless queues.')]].map(c=>'<button type="button" class="ad-btn" data-a="'+c[0]+'" style="text-align:left;white-space:normal;padding:10px 12px"><b style="display:block;font-size:15px">'+c[1]+' <small class="ad-new">'+L('nuevo','new')+'</small></b><span style="font-size:13px;color:var(--mu)">'+c[2]+'</span></button>').join('')+'</div></div>'+'<div class="ad-row"><span class="ad-lb">'+L('Manifestación: elige mapa y escenario','Demonstration: choose map and scenario')+'</span></div>'+'<div class="ad-row"><span class="ad-lb">'+L('Mapa (calles reales)','Map (real streets)')+'</span>'+seg('m',Object.keys(MD).map(k=>[k,esc(MD[k].n[EN()?1:0])+(MD[k].nw?' <small class="ad-new">'+L('nuevo','new')+'</small>':'')]))+'</div>'+
   '<div class="ad-row"><span class="ad-lb">'+L('Escenario','Scenario')+'</span>'+seg('e',Object.keys(ESC).map(k=>[k,ESC[k][EN()?1:0]]))+'</div>'+
   '<div class="ad-row"><span class="ad-lb">'+L('Hora','Time')+'</span>'+seg('h',[['dia',L('Día (18:00)','Day (18:00)')],['noche',L('Noche (21:30)','Night (21:30)')]])+'</div>'+
   '<div class="ad-row"><span class="ad-lb">'+L('Modo','Mode')+'</span>'+seg('d',[['f',L('Fácil','Easy')],['r',L('Realista','Realistic')]])+'<p class="ad-note" style="margin:0">'+(fac?L('Fácil: mandas 4 grupos grandes que se defienden solos. Lo importante son las decisiones por radio y 4 botones.','Easy: you command 4 big groups that defend themselves. What matters is the radio decisions and 4 buttons.'):L('Realista: subgrupos de 15, furgones y vallas, y todas las órdenes detalladas.','Realistic: sub-groups of 15, vans and barriers, and every detailed order.'))+'</p></div>'+
   (fac?'<div class="ad-row">':'<div class="ad-row"><span class="ad-lb">'+L('Efectivos de la UIP','UIP strength')+'</span>'+seg('g',[[1,L('1 grupo (≈50)','1 group (≈50)')],[2,L('2 grupos (≈100)','2 groups (≈100)')],[4,L('4 grupos (≈200)','4 groups (≈200)')],[6,L('6 grupos (≈300)','6 groups (≈300)')]]))+
   '<p class="ad-note">'+(fac?L('Tendrás 4 grupos UIP de unos 50 agentes (≈200), '+b.van+' furgones y '+b.fen+' tramos de valla, ya colocados en un despliegue sugerido: puedes pulsar Empezar directamente.','You get 4 UIP groups of about 50 officers (≈200), '+b.van+' vans and '+b.fen+' barrier sections, already placed in a suggested deployment: you can just press Start.'):L('Tendrás '+b.sub+' subgrupos de 15 agentes, '+b.van+' furgones (8 agentes por furgón) y '+b.fen+' tramos de valla (Estimación). Un grupo real son unos 50 agentes en 3 subgrupos.','You get '+b.sub+' sub-groups of 15 officers, '+b.van+' vans (8 officers per van) and '+b.fen+' barrier sections (estimate). A real group is about 50 officers in 3 sub-groups.'))+'</p></div>'+
   '<div class="ad-ctl"><button type="button" class="ad-btn pri" data-a="plan">'+L('Planificar el despliegue','Plan the deployment')+'</button></div></div>'; }
function intel(){ const md=G.md; const gs=G.groups; let t='';
  if(G.esc==='rival'){ const A=gs[0],B=gs[1]; t=L('Inteligencia: dos grupos radicales quieren enfrentarse. ','Intelligence: two radical groups want to clash. ')+'<b>'+L('Grupo A','Group A')+'</b> (≈'+A.n0*10+') '+L('en ','at ')+md.A[2]+'; <b>'+L('Grupo B','Group B')+'</b> (≈'+B.n0*10+') '+L('en ','at ')+md.B[2]+L('. Tu misión: que no lleguen a tocarse y que no haya daños.','. Your job: keep them apart and prevent damage.'); }
  else { const p=gs[0]; t=L('Inteligencia: manifestación comunicada de unas ','Intelligence: a notified demonstration of about ')+'<b>'+(Math.round(p.n0*10/100)*100)+L(' personas',' people')+'</b>'+L(' que saldrá de ',' leaving from ')+G.startN+L(' hacia ',' towards ')+md.dest[2]+'. '+(G.esc==='tensa'?L('Se espera un bloque radical (≈'+gs[1].n0*10+') con posibles cócteles molotov y barras.','A radical bloc is expected (≈'+gs[1].n0*10+') with possible Molotov cocktails and bars.'):L('No se esperan incidentes, pero todo puede cambiar.','No incidents are expected, but anything can change.'))+(md.prot?L(' Hay que proteger '+md.prot[2]+'.',' '+md.prot[3].replace(/^the /,'The ')+' must be protected.'):''); }
  return '<div class="ad-obj">'+esc(objTxt())+'</div><div class="ad-intel">'+t+'</div>'; }
function legend(){ return '<div class="ad-leg"><span style="--c:#e9dcae">'+L('Manifestantes','Protesters')+'</span>'+(G.groups.some(g=>g.k==='rad')||G.esc==='pac'?'<span style="--c:#ff8a3d">'+L('Radicales','Radicals')+'</span>':'')+(G.esc==='rival'?'<span style="--c:#ff5a5a">'+L('Grupo A','Group A')+'</span><span style="--c:#c48bff">'+L('Grupo B','Group B')+'</span>':'')+'<span style="--c:#ff2b2b">'+L('Violentos (lanzan objetos)','Violent (throwing objects)')+'</span><span class="ring" style="--c:#ff6b5a">'+L('Agitador identificado','Identified agitator')+'</span><span style="--c:#4ea1ff">'+L('UIP','UIP')+'</span><span style="--c:#1f4fa3">'+L('Furgón','Van')+'</span><span style="--c:#f2c94c">'+L('Valla','Barrier')+'</span><span style="--c:#5ac878">'+L('Salida abierta','Open exit')+'</span></div>'; }
function gameShell(){ page('<div id="ad-intel"></div><div id="ad-hud"></div><div class="ad-cv" id="ad-cvw"><canvas id="ad-cv"></canvas><div class="ad-zm"><button type="button" data-a="zin" aria-label="Zoom +">+</button><button type="button" data-a="zout" aria-label="Zoom −">−</button></div></div>'+legend()+'<div id="ad-ctl"></div><ul class="ad-log" id="ad-log"></ul>');
  CV=document.getElementById('ad-cv'); CTX=CV.getContext('2d'); G.layerC=layer(); G.cam=null; fit(); bindCanvas(); }
function objTxt(bare){ const d=G.md.dest[2], dd=EN()?d.replace(/^(la|el|los|las) /,''):d; const t=G.esc==='rival'?L('que los grupos radicales A y B no lleguen a pegarse, y sin heridos','keep radical groups A and B from clashing, with no injuries'):G.esc==='tensa'?L('que la marcha llegue a '+dd+' sin heridos, frenando solo a los violentos','get the march to '+dd+' with no injuries, stopping only the violent ones'):L('que la marcha llegue a '+dd+' sin heridos','get the march to '+dd+' with no injuries'); return bare?t.charAt(0).toUpperCase()+t.slice(1):L('Objetivo: ','Objective: ')+t; }
function tens(){ let m=0,v=false,e=false; G.groups.forEach(g=>{ if(g.n||G.phase==='plan'){ m=Math.max(m,g.T); if(g.violent&&g.n) v=true; if(g.T>=g.thr-8) e=true; } }); return v||e?[L('Peligrosa','Dangerous'),'#ff4b3e']:m>=45?[L('Tensa','Tense'),'#ff9b2f']:[L('Tranquila','Calm'),'#7ac36a']; }
function mood(g){ const T=g.T; if(g.violent) return [L('Violencia','Violent'),'#ff4b3e']; if(T>=g.thr-8) return [L('Al límite','On the edge'),'#ff6b3e']; if(T>=45) return [L('Tensión','Tense'),'#ff9b2f']; if(T>=25) return [L('Inquietud','Restless'),'#e8c547']; return [L('Calma','Calm'),'#7ac36a']; }
function hudHTML(){ const s=G.st, tn=tens(); let h='<div class="ad-obj">'+esc(objTxt())+'</div><div class="ad-hud"><span class="ad-tns">'+L('Tensión','Tension')+' <b class="ad-tn" style="background:'+tn[1]+'">'+tn[0]+'</b></span><span>'+L('Heridos civiles','Injured civilians')+' <b>'+s.civ+'</b></span><span>'+L('Policías heridos','Injured officers')+' <b>'+s.pol+'</b></span><span>'+L('Detenidos','Arrests')+' <b>'+s.det+'</b></span><span>'+L('Daños','Damage')+' <b>'+s.dmg+'</b></span></div><div class="ad-grp" aria-label="'+L('Ánimo de la multitud','Crowd mood')+'">';
  G.groups.forEach(g=>{ if(!g.n&&G.phase!=='plan') return; const n=G.phase==='plan'?g.n0:g.n; const T=Math.round(g.T); const md=mood(g); const tr=g.T15p==null?0:g.T-g.T15p; const ar=tr>3?'<span class="up" title="'+L('subiendo','rising')+'">▲</span>':tr<-3?'<span class="dn" title="'+L('bajando','falling')+'">▼</span>':'';
    const ag=G.phase==='plan'?0:G.ag.reduce((c,a)=>c+(a.g===g.id&&agit(a)?1:0),0);
    h+='<div class="ad-g"><div class="nm"><b style="color:'+GCOL[g.k]+'">'+esc(g.name)+'</b> · ≈'+(n*10)+' · '+(g.state==='leave'?(STN.leave||['',''])[EN()?1:0]:'<span style="color:'+md[1]+'">'+md[0]+'</span>')+ar+(ag&&!g.violent?' · <span class="agt">'+ag+(ag>1?L(' agitadores',' agitators'):L(' agitador',' agitator'))+'</span>':'')+'</div><div class="ad-bar" title="'+L('Ánimo','Mood')+' '+T+' / '+L('ruptura','breaking point')+' '+g.thr+'"><i style="width:'+Math.max(3,T)+'%;background:'+md[1]+'"></i><s style="left:'+g.thr+'%"></s></div></div>'; });
  return h+'</div>'; }
const ICO={warn:'<path d="M3 10v4h3l6 4V6L6 10H3z"/><path d="M15.5 8.5a5 5 0 0 1 0 7M18 6a8.5 8.5 0 0 1 0 12" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/>',smoke:'<path d="M7 18h10a4 4 0 0 0 .4-8 5.5 5.5 0 0 0-10.6-1.3A4.3 4.3 0 0 0 7 18z"/>',charge:'<path d="M3 11h12l-4.5-4.5L12 5l7 7-7 7-1.5-1.5L15 13H3z"/>',back:'<path d="M21 11H9l4.5-4.5L12 5l-7 7 7 7 1.5-1.5L9 13h12z"/>',vblock:'<rect x="2" y="9" width="20" height="6" rx="1.5"/><path d="M12 4v4M12 16v4" stroke="currentColor" stroke-width="1.8"/>',vaside:'<rect x="3" y="7" width="10" height="10" rx="1.5"/><path d="M15 12h6M18 9l3 3-3 3" fill="none" stroke="currentColor" stroke-width="1.8"/>'};
const BIG4=[['warn','Avisar','Warn'],['smoke','Humo','Smoke'],['charge','Cargar','Charge'],['back','Retirar','Withdraw']];
function bigBtn(o,dis){ return '<button type="button" class="ad-big'+(o[0]==='charge'?' warn':'')+'" data-o="'+o[0]+'"'+(dis?' disabled':'')+'><svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true">'+ICO[o[0]]+'</svg><span>'+L(o[1],o[2])+'</span></button>'; }
function liveFacil(u){ let h='<div style="width:100%"><div class="ad-ctl">'+[1,2,4].map(v=>'<button type="button" class="ad-btn'+(G.spd===v&&!G.pause?' pri':'')+'" data-spd="'+v+'">×'+v+'</button>').join('')+'<button type="button" class="ad-btn'+(G.pause?' pri':'')+'" data-a="pause">'+(G.pause?L('Seguir','Resume'):L('Pausa','Pause'))+'</button>'+dialBtn()+'<button type="button" class="ad-btn" data-a="end">'+L('Terminar','Finish')+'</button><button type="button" class="ad-btn" data-a="tut" aria-label="'+L('Cómo se juega','How to play')+'">?</button></div>';
  h+='<div class="ad-chips">'+G.units.map((x,i)=>'<button type="button" class="ad-btn'+(x===u?' sel':'')+(x.block?' blk':'')+'" data-u="'+i+'">'+x.nm+'</button>').join('')+G.vans.map((x,i)=>'<button type="button" class="ad-btn'+(x===u?' sel':'')+(x.on?' blk':'')+'" data-fu="'+i+'">'+x.nm+'</button>').join('')+'</div>';
  const hint='<p class="ad-note" style="margin:6px 0 0">'+L('Toca una calle para llevarlo allí. Si tocas cerca de otro grupo o furgón, se coloca a su lado. Para elegir otro, mantén pulsado o usa la lista.','Tap a street to send it there. Tap near another group or van and it lines up beside it. To pick another one, long-press it or use the list.')+'</p>';
  if(u&&u.van){ h+='<div class="ad-unit"><div class="t"><b>'+u.nm+'</b> · '+L('Furgón UIP','UIP van')+' · '+ustate(u)+'</div><div class="ad-big4 two">'+bigBtn(['vblock','Cruzar en la calle','Block the street'])+bigBtn(['vaside','Apartar','Move aside'])+'</div><div class="ad-ctl" style="margin-top:6px"><button type="button" class="ad-btn" data-o="desel">'+L('Soltar','Deselect')+'</button></div>'+hint+'</div>'; }
  else if(u){ h+='<div class="ad-unit"><div class="t"><b>'+u.nm+'</b> · '+(u.n-u.inj)+L(' agentes',' officers')+(u.inj?' · '+u.inj+L(' heridos',' injured'):'')+' · '+ustate(u)+'</div><div class="ad-big4">'+BIG4.map(o=>bigBtn(o,u.out)).join('')+'</div><div class="ad-ctl" style="margin-top:6px"><button type="button" class="ad-btn" data-a="more">'+(G.more?L('Menos ▴','Less ▴'):L('Más ▾','More ▾'))+'</button><button type="button" class="ad-btn" data-o="desel">'+L('Soltar','Deselect')+'</button></div>'+
      (G.more?'<div class="ad-ord" style="margin-top:6px">'+ORD.filter(o=>['hold','open','prot','det','pace'].indexOf(o[0])>=0).map(o=>'<button type="button" class="ad-btn" data-o="'+o[0]+'"'+(u.out?' disabled':'')+'>'+(o[0]==='pace'?(u.run?L('Ir al paso','Walk'):L('Ir a la carrera','Run')):L(o[1],o[2]))+'</button>').join('')+'</div>':'')+hint+'</div>'; }
  else h+='<p class="ad-note">'+L('Toca un grupo azul (G1–G4) o un furgón para darle órdenes. Se defienden solos: tú decides con la radio y los 4 botones.','Tap a blue group (G1–G4) or a van to give it orders. They defend themselves: you decide with the radio and the 4 buttons.')+'</p>';
  return h+'</div>'; }
function tutHTML(){ const k=G.tut, S=[[L('Tu misión','Your mission'),objTxt(true)+'. '+L('Tienes 4 grupos UIP (≈200 agentes) y los furgones ya colocados.','You have 4 UIP groups (≈200 officers) and the vans already in place.')],[L('Mover','Moving'),L('Toca un grupo azul (G1…G4) y luego una calle: irá hasta allí por las calles. Los grupos aguantan la línea, se defienden solos y protegen los furgones.','Tap a blue group (G1…G4), then a street: it walks there along the streets. Groups hold the line, defend themselves and protect the vans.')],[L('4 botones','4 buttons'),L('Avisar (megáfono) primero: la ley exige avisar antes de usar la fuerza. Humo y Cargar, solo contra violentos. Retirar baja la tensión. El botón Diálogo (arriba) manda un equipo a hablar con los organizadores: calma a los grupos pacíficos.','Warn (megaphone) first: the law requires a warning before using force. Smoke and Charge only against violent people. Withdraw lowers the tension. The Dialogue button (top) sends a team to talk to the organisers: it calms peaceful groups.')],[L('La radio','The radio'),L('Cuando llame la radio, el juego se para: elige una opción. Es lo más importante. Arriba ves el ánimo de cada grupo (Calma, Inquietud, Tensión, Al límite) y la raya blanca donde estalla. Los puntos rojos son violentos; con aro rojo, agitadores identificados: detenlos sin cargar contra todos.','When the radio calls, the game pauses: pick an option. It matters most. On top you see each group’s mood (Calm, Restless, Tense, On the edge) and the white mark where it breaks. Red dots are violent people; with a red ring, identified agitators: arrest them without charging everyone.')]];
  const s=S[k-1]; return '<div class="ad-tut" role="dialog"><div class="rh">'+L('Cómo se juega','How to play')+' · '+k+'/4</div><div class="tt">'+s[0]+'</div><p>'+s[1]+'</p><div class="ad-ctl">'+(k<4?'<button type="button" class="ad-btn pri" data-a="tutn">'+L('Siguiente','Next')+'</button><button type="button" class="ad-btn" data-a="tutx">'+L('Saltar','Skip')+'</button>':'<button type="button" class="ad-btn pri" data-a="tutx">'+L('¡A jugar!','Let’s play!')+'</button>')+'</div></div>'; }
function render(){ if(!G||!document.getElementById('ad-ctl')) return; const ctl=document.getElementById('ad-ctl');
  document.getElementById('ad-hud').innerHTML=G.phase==='plan'?'':hudHTML();
  if(G.phase==='plan'){ document.getElementById('ad-intel').innerHTML=intel(); const b=G.bud, used={sub:G.units.length,van:G.vans.length,fen:G.fences.length};
    const tb=(k,lab)=>'<button type="button" data-tool="'+k+'" class="'+(G.tool===k?'on':'')+'">'+lab+'</button>';
    ctl.innerHTML='<div style="width:100%">'+(FAC()?'<div class="ad-ctl" style="margin:0 0 8px"><button type="button" class="ad-btn pri ad-go" data-a="start"'+(G.units.length?'':' disabled')+'>'+L('Empezar','Start')+'</button></div><p class="ad-note" style="margin:0 0 8px">'+L('Ya tienes un despliegue sugerido colocado: pulsa Empezar, o cámbialo antes.','A suggested deployment is already in place: press Start, or change it first.')+'</p>':'')+'<div class="ad-seg">'+tb('sub',(FAC()?L('Grupo ','Group '):L('Subgrupo ','Sub-group '))+(b.sub-used.sub))+tb('van',L('Furgón ','Van ')+(b.van-used.van))+tb('fen',L('Valla ','Barrier ')+(b.fen-used.fen))+tb('del',L('Quitar','Remove'))+'</div>'+
     '<p class="ad-note" style="margin-top:6px">'+(FAC()?L('Toca una calle para colocar. Un grupo cubre hasta 30 m; si pones dos cosas en la misma calle, se colocan una al lado de la otra. La línea amarilla es la ruta prevista; los puntos verdes, las salidas abiertas.','Tap a street to place. A group covers up to 30 m; two items on the same street are placed side by side. The yellow line is the expected route; green dots are open exits.'):L('Toca una calle para colocar. Se colocan cruzando la calle: un subgrupo cubre unos 15 m. Si pones dos en la misma calle, se colocan uno al lado del otro. La línea amarilla es la ruta prevista; los puntos verdes, las salidas abiertas.','Tap a street to place. Items are placed across the street: a sub-group covers about 15 m. Two on the same street are placed side by side. The yellow line is the expected route; green dots are open exits.'))+(G.routeCut?' <b style="color:#ffb3aa">'+L('Has cortado la ruta prevista: la marcha se encontrará el paso cerrado.','You have cut the expected route: the march will find its way blocked.')+'</b>':'')+'</p>'+
     '<div class="ad-ctl"><button type="button" class="ad-btn" data-a="auto">'+L('Despliegue sugerido','Suggested deployment')+'</button><button type="button" class="ad-btn" data-a="clear">'+L('Borrar todo','Clear all')+'</button>'+(FAC()?'':'<button type="button" class="ad-btn pri" data-a="start"'+(G.units.length?'':' disabled')+'>'+L('Empezar','Start')+'</button>')+'<button type="button" class="ad-btn" data-a="setup">'+L('Ajustes','Settings')+'</button></div></div>';
    document.getElementById('ad-log').innerHTML=''; draw(); return; }
  const ri=document.getElementById('ad-intel'); if(G.phase==='live'&&G.tut) ri.innerHTML=tutHTML(); else if(G.phase==='live'&&G.radio){ const r=G.radio; ri.innerHTML='<div class="ad-radio'+(FAC()?' f':'')+'" role="alertdialog"><div class="rh">'+L('Radio','Radio')+' · '+esc(r.from)+' · '+clock(r.t)+'</div><div class="rt">«'+esc(r.txt)+'»</div><div class="ro">'+r.opts.map(o=>'<button type="button" class="ad-btn'+(o==='charge'?' warn':'')+'" data-r="'+o+'">'+L(RO[o][0],RO[o][1])+'</button>').join('')+'</div><div class="ad-note">'+L('Partida en pausa hasta que decidas.','Game paused until you decide.')+'</div></div>'; } else ri.innerHTML='';
  if(G.phase==='live'&&FAC()) ctl.innerHTML=liveFacil(G.sel);
  else if(G.phase==='live'){ const u=G.sel;
    let h='<div style="width:100%"><div class="ad-ctl">'+[1,2,4].map(v=>'<button type="button" class="ad-btn'+(G.spd===v&&!G.pause?' pri':'')+'" data-spd="'+v+'">×'+v+'</button>').join('')+'<button type="button" class="ad-btn'+(G.pause?' pri':'')+'" data-a="pause">'+(G.pause?L('Seguir','Resume'):L('Pausa','Pause'))+'</button>'+dialBtn()+'<button type="button" class="ad-btn" data-a="end">'+L('Terminar','Finish')+'</button></div>';
    h+='<div class="ad-chips">'+G.units.map((x,i)=>'<button type="button" class="ad-btn'+(x===u?' sel':'')+(x.block?' blk':'')+'" data-u="'+i+'">'+x.nm+'</button>').join('')+G.vans.map((x,i)=>'<button type="button" class="ad-btn'+(x===u?' sel':'')+(x.on?' blk':'')+'" data-fu="'+i+'">'+x.nm+'</button>').join('')+'</div>';
    const hint='<p class="ad-note" style="margin:6px 0 0">'+L('Toca una calle del mapa para llevarlo allí por las calles. Toca otra vez el grupo, o un edificio, para soltarlo.','Tap a street on the map to send it there along the streets. Tap the group again, or a building, to deselect it.')+'</p>';
    if(u&&u.van){ h+='<div class="ad-unit"><div class="t"><b>'+u.nm+'</b> · '+L('Furgón UIP','UIP van')+' · '+ustate(u)+'</div><div class="ad-ord"><button type="button" class="ad-btn" data-o="vblock">'+L('Cruzar en la calle','Block the street')+'</button><button type="button" class="ad-btn" data-o="vaside">'+L('Apartar (dejar salida)','Move aside (open exit)')+'</button><button type="button" class="ad-btn" data-o="desel">'+L('Soltar','Deselect')+'</button></div>'+hint+'</div>'; }
    else if(u){ h+='<div class="ad-unit"><div class="t"><b>'+u.nm+'</b> · '+(u.n-u.inj)+L(' agentes',' officers')+(u.inj?' · '+u.inj+L(' heridos',' injured'):'')+' · '+ustate(u)+'</div><div class="ad-ord">'+ORD.map(o=>'<button type="button" class="ad-btn'+(o[0]==='charge'?' warn':'')+'" data-o="'+o[0]+'"'+(u.out?' disabled':'')+'>'+(o[0]==='pace'?(u.run?L('Ir al paso','Walk'):L('Ir a la carrera','Run')):L(o[1],o[2]))+'</button>').join('')+'<button type="button" class="ad-btn" data-o="desel">'+L('Soltar','Deselect')+'</button></div>'+hint+'</div>'; }
    else h+='<p class="ad-note">'+L('Toca un subgrupo o un furgón en el mapa (o en la lista) para seleccionarlo; luego toca dónde quieres llevarlo.','Tap a sub-group or a van on the map (or in the list) to select it, then tap where you want it to go.')+'</p>';
    ctl.innerHTML=h+'</div>'; }
  if(G.phase==='result'){ const v=verdict(), s=G.st; G.v=v;
    ctl.innerHTML='<div class="ad-res" id="ad-res" style="width:100%"><div class="ad-sc"><span class="n">'+v.sc+'</span><span class="g">'+v.gr+'</span><span class="ad-note">'+L('de 100','out of 100')+'</span></div><div class="ad-press">'+L('La prensa: ','The press: ')+v.head+'</div>'+
      '<div class="ad-kv"><div><span>'+L('Heridos civiles','Injured civilians')+'</span><b>'+s.civ+'</b></div><div><span>'+L('Policías heridos','Injured officers')+'</span><b>'+s.pol+'</b></div><div><span>'+L('Detenidos','Arrests')+'</span><b>'+s.det+'</b></div><div><span>'+L('… de ellos violentos','… of them violent')+'</span><b>'+s.detV+'</b></div><div><span>'+L('Daños (incidentes)','Damage (incidents)')+'</span><b>'+s.dmg+'</b></div><div><span>'+L('Denuncias por la actuación','Complaints about the police')+'</span><b>'+v.den+'</b></div><div><span>'+L('Proporcionalidad','Proportionality')+'</span><b>'+((G.inc.cargaPac||0)+(G.inc.humoPac||0)+(G.inc.detArb||0)?L('fallos','failures'):L('correcta','correct'))+'</b></div><div><span>'+L('Reacción de la prensa','Press reaction')+'</span><b>'+(v.pr>0?'+':'')+v.pr+'</b></div><div><span>'+L('Decisiones por radio','Radio decisions')+'</span><b>'+v.rg+'/'+v.rn+'</b></div></div>'+
      '<h3>'+L('Cómo fue la tensión','How tension went')+'</h3>'+tlSVG()+docHTML()+(v.ok.length?'<h3>'+L('Lo que hiciste bien','What you did right')+'</h3><ul class="ad-ok">'+v.ok.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+(v.ko.length?'<h3>'+L('Lo que hiciste mal','What you did wrong')+'</h3><ul class="ad-ko">'+v.ko.map(x=>'<li>'+esc(x)+'</li>').join('')+'</ul>':'')+
      '<p class="ad-note" style="margin-top:8px">'+L('Puntuación y consecuencias: Estimación de M.A.T según los principios de la ley (proporcionalidad y aviso previo).','Score and consequences: M.A.T estimate based on the legal principles (proportionality and prior warning).')+'</p>'+
      '<div class="ad-ctl"><button type="button" class="ad-btn pri" data-a="rematch">'+L('Revancha','Rematch')+'</button><button type="button" class="ad-btn" data-a="replay">'+L('Repetir (misma semilla)','Replay (same seed)')+'</button><button type="button" class="ad-btn" data-a="share">'+L('Compartir','Share')+'</button><button type="button" class="ad-btn" data-a="setup">'+L('Ajustes','Settings')+'</button></div></div>'; }
  document.getElementById('ad-log').innerHTML=G.log.slice(0,40).map(e=>'<li class="'+e.c+'"><time>'+clock(e.t)+'</time>'+esc(e.txt)+'</li>').join(''); draw(); }

/* ---------------- planificación ---------------- */
function tracePath(F,x,y,max){ const out=[[x,y]]; let i=ci(x,y); if(i<0||F[i]>=1e9) return out; const gw=G.gw;
  for(let k=0;k<(max||2000);k++){ let bi=-1,bv=F[i]; for(const j of [i-1,i+1,i-gw,i+gw,i-gw-1,i-gw+1,i+gw-1,i+gw+1]){ if(j<0||j>=F.length) continue; if(F[j]<bv){ bv=F[j]; bi=j; } } if(bi<0) break; i=bi; if(k%2===0) out.push([(i%gw)*CELL+1,Math.floor(i/gw)*CELL+1]); }
  out.push([(i%gw)*CELL+1,Math.floor(i/gw)*CELL+1]); return out; }
function planUpdate(){ computeFields(); if(G.esc==='rival'){ const A=G.groups[0],B=G.groups[1]; const F=bfs([ci(B.st[0],B.st[1])],G.blk); const fr=F[ci(A.st[0],A.st[1])]; G.route=tracePath(F,A.st[0],A.st[1]); G.routeCut=false; if(fr>=1e9) G.route=[A.st,B.st]; }
  else { const s=G.groups[0].st; const v=G.fields.dest[ci(s[0],s[1])]; G.routeCut=v>=1e9; G.route=G.routeCut?tracePath(bfs([ci(G.dest[0],G.dest[1])],G.bld),s[0],s[1]):tracePath(G.fields.dest,s[0],s[1]); } }
function sideSlot(a,list,step){ for(let k=0;k<6;k++){ const hit=list.find(o=>Math.hypot(o.x-a.x,o.y-a.y)<step*0.6); if(!hit) return a; const c=Math.cos(a.ang), s=Math.sin(a.ang); let moved=false; for(const sg of [1,-1]){ const nx=hit.x+c*step*sg, ny=hit.y+s*step*sg; if(free0(nx,ny)&&!list.some(o=>Math.hypot(o.x-nx,o.y-ny)<step*0.6)){ a={x:nx,y:ny,ang:a.ang,len:a.len,w:a.w}; moved=true; break; } } if(!moved) return a; } return a; }
const GAP=1.2;
function toast(es,en){ if(G&&!G.quiet) G.toast={txt:L(es,en),until:performance.now()+1800}; }
function fp(o){ if(o.van) return {len:8,dep:5}; if(o.fen) return {len:o.len||20,dep:2.4}; if(o.block) return {len:o.len||15,dep:3.2}; const d=o.big?9:6; return {len:d,dep:d}; }
function occ(skip){ const out=[]; G.units.forEach(u=>{ if(u===skip||u.out||u.st==='move'||u.st==='charge'||u.st==='detain') return; out.push(u); }); G.vans.forEach(v=>{ if(v!==skip&&!v.mv) out.push(v); }); G.fences.forEach(f=>{ if(f!==skip&&f.on) out.push(f); }); return out; }
/* hueco libre en la calle: se colocan uno al lado del otro a lo ancho de la calle (ancho = edificios OSM); si no cabe, en otra fila a lo largo de la calle; si tampoco, null («No cabe aquí») */
function slot(x,y,kind,maxL,skip){ const others=occ(skip); const myDep=kind==='v'?5:kind==='f'?2.4:3.2, pitch=kind==='v'?5.6:kind==='f'?3:(maxL>20?8:4.2);
  const a0=across(x,y,60); const nx=-Math.sin(a0.ang), ny=Math.cos(a0.ang);
  for(const r of [0,1,-1,2,-2,3,-3]){ const px=x+nx*r*pitch, py=y+ny*r*pitch; if(!free0(px,py)) continue; const a=r?across(px,py,60):a0; const w=a.w;
    const len=kind==='v'?8:Math.max(4,Math.min(w+1,maxL)); const c=Math.cos(a.ang), sn=Math.sin(a.ang), n1=-sn, n2=c; const half=Math.max(0,(w+1)/2-len/2);
    const t0=Math.max(-half,Math.min(half,(px-a.x)*c+(py-a.y)*sn)); const bl=[];
    others.forEach(o=>{ const f=fp(o), rx=o.x-a.x, ry=o.y-a.y, oa=o.ang||0, ca=Math.abs(Math.cos(oa-a.ang)), sa=Math.abs(Math.sin(oa-a.ang)); const dO=f.len/2*sa+f.dep/2*ca; if(Math.abs(rx*n1+ry*n2)>=dO+myDep/2) return; const t=rx*c+ry*sn, hl=f.len/2*ca+f.dep/2*sa; bl.push([t-hl-GAP-len/2,t+hl+GAP+len/2]); });
    let best=null; const K=Math.ceil(2*half/0.5)+1; for(let k=0;k<=K&&best==null;k++){ for(const sg of (k?[1,-1]:[1])){ const t=t0+sg*k*0.5; if(t<-half-0.01||t>half+0.01) continue; if(bl.some(b=>t>b[0]&&t<b[1])) continue; if(!free0(a.x+c*t,a.y+sn*t)) continue; best=t; break; } }
    if(best==null) continue; return {x:a.x+c*best,y:a.y+sn*best,ang:a.ang,len,w}; }
  return null; }
function addUnit(x,y){ const big=FAC(); if(G.units.length>=G.bud.sub){ toast(big?'Ya has colocado tus 4 grupos':'No te quedan subgrupos',big?'All 4 groups are placed':'No sub-groups left'); return false; } const a=slot(x,y,'u',big?30:15.5,null); if(!a){ toast('No cabe aquí','No room here'); return false; } const u={nm:(big?'G':'S')+(G.units.length+1),n:big?50:15,big:big?1:0,inj:0,x:a.x,y:a.y,ang:a.ang,len:a.len,block:true,st:'hold',home:[a.x,a.y]}; G.units.push(u); return u; }
function addVan(x,y){ if(G.vans.length>=G.bud.van){ toast('No te quedan furgones','No vans left'); return false; } const a=slot(x,y,'v',6,null); if(!a){ toast('No cabe aquí','No room here'); return false; } G.vans.push({x:a.x,y:a.y,ang:a.ang,on:1,van:1,nm:'F'+(G.vans.length+1)}); return true; }
function addFence(x,y){ if(G.fences.length>=G.bud.fen){ toast('No te quedan vallas','No barriers left'); return false; } const a=slot(x,y,'f',20,null); if(!a){ toast('No cabe aquí','No room here'); return false; } G.fences.push({x:a.x,y:a.y,ang:a.ang,len:a.len,on:1,fen:1}); return true; }
function removeNear(x,y){ const r=Math.max(12,16/G.cam.s); let best=null,bd=r,arr=null; [[G.units],[G.vans],[G.fences]].forEach(([A])=>A.forEach((o,i)=>{ const d=Math.hypot(o.x-x,o.y-y); if(d<bd){bd=d;best=i;arr=A;} })); if(arr){ arr.splice(best,1); G.units.forEach((u,i)=>u.nm=(u.big?'G':'S')+(i+1)); G.vans.forEach((v,i)=>v.nm='F'+(i+1)); return true; } return false; }
function autoDeploy(){ G.quiet=1; try{ autoDeploy0(); } finally { G.quiet=0; G.toast=null; } }
function autoDeploy0(){ G.units=[]; G.vans=[]; G.fences=[]; computeFields(); const md=G.md, R=rng(G.cfg.s+7); const placed=[];
  const far=(x,y,d)=>placed.every(p=>Math.hypot(p[0]-x,p[1]-y)>=d);
  const put=(x,y,van)=>{ if(!free0(x,y)||!far(x,y,38)) return false; const u=addUnit(x,y); if(!u) return false; placed.push([u.x,u.y]); if(van){ const c=Math.cos(u.ang+Math.PI/2), s=Math.sin(u.ang+Math.PI/2); for(const sg of [1,-1]){ const vx=u.x+c*9*sg, vy=u.y+s*9*sg; if(free0(vx,vy)){ addVan(vx,vy); break; } } } return true; };
  if(G.esc==='rival'){ const A=G.groups[0],B=G.groups[1]; const F=bfs([ci(B.st[0],B.st[1])],G.bld); const P=tracePath(F,A.st[0],A.st[1]); const n=P.length; const used=[];
    for(let rep=0;rep<4&&G.units.length<G.bud.sub-1;rep++){ let best=null; for(let k=Math.floor(n*0.3);k<Math.floor(n*0.7);k+=2){ const p=P[k]; if(used.some(q=>Math.hypot(q[0]-p[0],q[1]-p[1])<45)) continue; const a=across(p[0],p[1],60); if(!best||a.w<best.w) best={w:a.w,p}; } if(!best) break; used.push(best.p);
      const need=Math.max(1,Math.ceil((best.w+1)/(FAC()?30:15))); for(let j=0;j<need;j++){ const u=addUnit(best.p[0],best.p[1]); if(!u) break; placed.push([u.x,u.y]); } addFence(best.p[0]+(R()-.5)*2,best.p[1]+(R()-.5)*2); const u0=G.units[G.units.length-1]; if(u0){ const c=Math.cos(u0.ang+Math.PI/2), sn=Math.sin(u0.ang+Math.PI/2); if(free0(u0.x+c*10,u0.y+sn*10)) addVan(u0.x+c*10,u0.y+sn*10); } } }
  else { const s=G.groups[0].st; const path=tracePath(G.fields.dest,s[0],s[1]); const onPath=(x,y)=>path.some(p=>Math.hypot(p[0]-x,p[1]-y)<22);
    if(md.prot){ const p=snapPt(md.prot[0],md.prot[1]+30); put(p[0],p[1],true); }
    const F=G.fields.dest; const cand=[]; for(let i=0;i<F.length;i++){ const v=F[i]*CELL; if(v>85&&v<150&&!G.bld[i]) cand.push(i); }
    for(let k=0;k<400&&G.units.length<Math.min(G.bud.sub,md.prot?6:5);k++){ const i=cand[Math.floor(R()*cand.length)]; const x=(i%G.gw)*CELL+1, y=Math.floor(i/G.gw)*CELL+1; if(onPath(x,y)) continue; const a=across(x,y,40); if(a.w>26) continue; put(x,y,true); } }
  planUpdate(); render(); }
/* ---------------- entrada (tocar, arrastrar) ---------------- */
function bindCanvas(){ let st=null; const pos=e=>{ const r=CV.getBoundingClientRect(); return [e.clientX-r.left,e.clientY-r.top]; };
  CV.addEventListener('pointerdown',e=>{ const p=pos(e); st={x:p[0],y:p[1],ox:G.cam.ox,oy:G.cam.oy,drag:false,t0:performance.now()}; try{CV.setPointerCapture(e.pointerId);}catch(_){} });
  CV.addEventListener('pointermove',e=>{ if(!st) return; const p=pos(e); const dx=p[0]-st.x, dy=p[1]-st.y; if(!st.drag&&Math.hypot(dx,dy)>7&&G.cam.z>1) st.drag=true; if(st.drag){ G.cam.ox=st.ox+dx; G.cam.oy=st.oy+dy; clampCam(); draw(); } });
  CV.addEventListener('pointerup',e=>{ if(!st) return; const was=st.drag, lng=performance.now()-st.t0>450; st=null; if(was) return; const p=pos(e); tap((p[0]-G.cam.ox)/G.cam.s,(p[1]-G.cam.oy)/G.cam.s,lng); });
  CV.addEventListener('wheel',e=>{ e.preventDefault(); const p=pos(e); zoom(e.deltaY<0?1.25:0.8,p[0],p[1]); },{passive:false}); }
function tap(x,y,lng){ if(x<0||y<0||x>G.M.w||y>G.M.h) return;
  if(G.phase==='plan'){ if(G.tool==='del'){ removeNear(x,y); } else { if(!free0(x,y)){ const p=snapPt(x,y); if(Math.hypot(p[0]-x,p[1]-y)>Math.max(10,14/G.cam.s)) return; x=p[0]; y=p[1]; } if(G.tool==='sub') addUnit(x,y); else if(G.tool==='van') addVan(x,y); else if(G.tool==='fen') addFence(x,y); } planUpdate(); render(); return; }
  if(G.phase!=='live') return;
  if(G.pend){ const u=G.pend.u; G.pend=null; if(!u.out) chargeTo(u,x,y); render(); return; }
  /* tocar un grupo o un furgón lo selecciona; con algo seleccionado, tocar una calle lo lleva allí por las calles; tocar un edificio (o el mismo grupo) lo suelta */
  let best=null,bd=Math.max(10,24/G.cam.s); const sd=(o,L_)=>{ if(!o.block&&!o.van) return Math.hypot(o.x-x,o.y-y); const c=Math.cos(o.ang), s=Math.sin(o.ang); const t=Math.max(-L_/2,Math.min(L_/2,(x-o.x)*c+(y-o.y)*s)); return Math.hypot(o.x+c*t-x,o.y+s*t-y); };
  G.units.forEach(u=>{ if(u.out) return; let d=sd(u,u.len||15); if(u.bw&&FAC()) d=Math.min(d,Math.hypot(u.bw[0]-x,u.bw[1]-y)); if(d<bd){bd=d;best=u;} }); /* tocar la insignia G1–G4 también lo selecciona */ G.vans.forEach(v=>{ const d=sd(v,6); if(d<bd){bd=d;best=v;} });
  /* con algo seleccionado, tocar cerca de otra unidad lo lleva allí (se coloca al lado, sin montarse); para seleccionar otra, pulsación larga o la lista */
  if(best){ if(G.sel&&best!==G.sel&&!lng&&!G.sel.out){ moveTo(G.sel,best.x,best.y); render(); return; } G.sel=G.sel===best?null:best; G.more=false; render(); return; }
  if(G.sel){ if(!free0(x,y)){ const p=snapPt(x,y); if(Math.hypot(p[0]-x,p[1]-y)>Math.max(6,10/G.cam.s)){ G.sel=null; render(); return; } x=p[0]; y=p[1]; } moveTo(G.sel,x,y); render(); return; }
  render(); }
function vorder(v,o){ if(o==='vblock'){ v.mv=0; const a=slot(v.x,v.y,'v',6,v); if(!a){ toast('No cabe aquí','No room here'); return; } v.x=a.x; v.y=a.y; v.ang=a.ang; v.on=1; lg(v.nm+L(' se cruza y corta la calle ',' parks across and blocks the street ')+nearName(v.x,v.y)); }
  else if(o==='vaside'){ v.mv=0; v.on=0; lg(v.nm+L(' se aparta y deja la calle libre',' moves aside and leaves the street open'),'good'); }
  G.dirty=true; render(); }

/* ---------------- movimiento y reacciones (mejora nov. 2026): cada agente se mueve como una persona, con aceleración, y reacciona a lo que ve u oye cerca ---------------- */
function snap(){ G.ag.forEach(a=>{ a.px=a.x; a.py=a.y; }); G.units.forEach(u=>{ u.pD=u.D?u.D.map(p=>[p[0],p[1]]):null; }); G.vans.forEach(v=>{ v.px=v.rx==null?v.x:v.rx; v.py=v.ry==null?v.y:v.ry; v.pa=v.ra==null?v.ang:v.ra; }); (G.evac||[]).forEach(e=>{ e.px=e.x; e.py=e.y; }); }
/* rasgos fijos de cada unidad (salen de la semilla: cada partida distinta, pero la misma partida se repite igual) */
function trait(u){ if(u.rd==null){ const h=Math.abs(Math.sin((u.home?u.home[0]*12.9898+u.home[1]*78.233:0)+(G.cfg.s%997)*0.37+(u.nm||'').length))*43758.5453; const f=h-Math.floor(h); u.rd=0.35+f*0.55; u.pr=f; } return u; }
/* formación objetivo de cada agente: línea (cordón), columna que sigue el camino (sin girar en bloque) o línea de carga */
function dotsT(u){ const out=[]; const n=Math.max(1,u.n-u.inj);
  if(u.block||u.st==='hold'){ const c=Math.cos(u.ang), s=Math.sin(u.ang); const f=u.fc||0, fx=Math.cos(f), fy=Math.sin(f); const back=(u.gg||0)+(u.brc||0)*0.7;
    for(let k=0;k<n;k++){ const t=n>1?k/(n-1)-0.5:0; let x=u.x+c*t*u.len-fx*back, y=u.y+s*t*u.len-fy*back; out.push([x,y]); } return out; }
  if(u.st==='charge'){ const h=u.hd||0, fx=Math.cos(h), fy=Math.sin(h), nx=-fy, ny=fx; let wl=0,wr=0; const W=(u.big?22:11)/2; while(wl<W&&free0(u.x+nx*(wl+1),u.y+ny*(wl+1))) wl++; while(wr<W&&free0(u.x-nx*(wr+1),u.y-ny*(wr+1))) wr++;
    const rows=wl+wr<n*0.6?2:1, per=Math.ceil(n/rows); for(let k=0;k<n;k++){ const r=Math.floor(k/per), j=k%per; const t=per>1?j/(per-1):0.5; const off=-wr+t*(wl+wr); out.push([u.x+nx*off-fx*r*1.4,u.y+ny*off-fy*r*1.4]); } return out; }
  const tr=u.tr||[[u.x,u.y]]; for(let k=0;k<n;k++){ const r=Math.floor(k/3), col=k%3-1; let need=r*1.3, i=0, px=u.x, py=u.y, tx=Math.cos(u.hd||0), ty=Math.sin(u.hd||0);
    let prev=[u.x,u.y]; for(i=0;i<tr.length;i++){ const q=tr[i]; const seg=Math.hypot(q[0]-prev[0],q[1]-prev[1]); if(seg>=need&&seg>0){ const f=need/seg; px=prev[0]+(q[0]-prev[0])*f; py=prev[1]+(q[1]-prev[1])*f; tx=(prev[0]-q[0])/seg; ty=(prev[1]-q[1])/seg; need=-1; break; } need-=seg; prev=q; if(seg>0){ tx=(i?tr[i-1][0]-q[0]:u.x-q[0])/seg; ty=(i?tr[i-1][1]-q[1]:u.y-q[1])/seg; } }
    if(need>=0){ px=prev[0]-tx*need; py=prev[1]-ty*need; if(!free0(px,py)){ px=prev[0]; py=prev[1]; } }
    let lx=px-ty*col*1.2, ly=py+tx*col*1.2; if(!free0(lx,ly)){ lx=px-ty*col*0.5; ly=py+tx*col*0.5; if(!free0(lx,ly)){ lx=px; ly=py; } } out.push([lx,ly]); }
  return out; }
function dotsOf(u){ if(u.Dr) return u.Dr; if(G.phase==='plan'||!u.D) return dotsT(u); return u.D; }
function nearestVan(x,y){ let b=null,bd=1e9; G.vans.forEach(v=>{ if(v.burn) return; const d=Math.hypot(v.x-x,v.y-y); if(d<bd){ bd=d; b=v; } }); return bd<160?b:null; }
/* el grupo percibe la amenaza (impactos, violentos armados cerca, empujones), duda un instante (su propio reflejo) y reacciona: se cubre con los escudos, cede algo de terreno, encara al que empuja; un herido sale andando con un compañero hacia el furgón */
function formUnits(dt){ hash(); const imp=(G.imp||[]).filter(p=>G.t-p.t<3);
  G.units.forEach(u=>{ trait(u); const n=Math.max(1,u.n-u.inj);
    if(u.lst!==u.st){ if(u.st==='move'||u.st==='charge'||u.st==='detain'){ if(!(u.lst==='move'||u.lst==='charge'||u.lst==='detain')) u.v=0; if(u.st!=='charge'&&u.lst!=='move'&&u.lst!=='detain') u.tr=null; } u.lst=u.st; }
    /* rastro para la columna */
    if(!u.tr){ u.tr=[]; const h=u.hd!=null?u.hd:(u.fc||0); for(let k=1;k<=20;k++){ const x=u.x-Math.cos(h)*k*1.2, y=u.y-Math.sin(h)*k*1.2; if(!free0(x,y)) break; u.tr.push([x,y]); } }
    const h0=u.tr.length?u.tr[0]:null; if(!h0||Math.hypot(h0[0]-u.x,h0[1]-u.y)>0.6){ u.tr.unshift([u.x,u.y]); if(u.tr.length>60) u.tr.length=60; }
    /* amenaza percibida */
    let ni=0, ix=0, iy=0; const R2=Math.max(9,(u.len||8)/2+5); const inc_=G.proj.filter(p=>p.k!==9&&G.t-p.t0>=u.rd*0.6&&Math.hypot(p.x1-u.x,p.y1-u.y)<R2+3).map(p=>({x:p.x1,y:p.y1,t:G.t-0.4,k:p.k})); /* ven venir el objeto: se cubren antes de que caiga */ inc_.forEach(p=>{ ni++; ix+=p.x; iy+=p.y; }); imp.forEach(p=>{ const d=Math.hypot(p.x-u.x,p.y-u.y); if(d<R2+4){ ni+=p.k===2?2:1; ix+=p.x; iy+=p.y; } });
    let nv=0, vx=0, vy=0, nc=0; const VL=[]; eachNear(u.x,u.y,R2+6,(a,j,d)=>{ if(a.fl>G.t) return; const g=G.groups[a.g]; if(a.arm&&(g.violent||agit(a))&&(d<7||los(a.x,a.y,u.x,u.y))){ nv++; vx+=a.x; vy+=a.y; VL.push(a); } if(d<R2) nc++; });
    const thr=Math.min(1,ni*0.35+nv*0.1+(nc>12?0.25:0));
    if(thr>0.05){ if(!(u.seeT>0)) u.seeT=G.t; } else u.seeT=0;
    const reacted=u.seeT>0&&G.t-u.seeT>=u.rd;
    const tgt=reacted?thr:0; u.brc=(u.brc||0)+Math.max(-0.25,Math.min(0.8,tgt-(u.brc||0)));
    if(reacted&&ni){ u.gg=Math.min(u.big?2.6:1.8,(u.gg||0)+0.35*ni*dt); } else u.gg=Math.max(0,(u.gg||0)-0.3*dt);
    if(reacted&&(u.block||u.st==='hold'||u.st==='aside')&&(ni||nv)){ const sx=ni?ix/ni:vx/nv, sy=ni?iy/ni:vy/nv; const of=u.fc; faceTo(u,sx,sy); const want=Math.atan2(sy-u.y,sx-u.x); let dd=want-u.fc; while(dd>Math.PI) dd-=2*Math.PI; while(dd<-Math.PI) dd+=2*Math.PI;
      if(u.block){ const tgt_=u.fc+Math.max(-0.6,Math.min(0.6,dd))*0.85; let d2=tgt_-(of==null?tgt_:of); while(d2>Math.PI) d2-=2*Math.PI; while(d2<-Math.PI) d2+=2*Math.PI; u.fc=(of==null?tgt_:of)+(Math.abs(d2)>1.2?d2:d2*0.6); } else u.fc=of+dd*0.5; } /* el escudo se inclina hacia donde vienen los objetos */
    /* objetivos por agente */
    const T=dotsT(u); const fx=Math.cos(u.fc||0), fy=Math.sin(u.fc||0); const line=u.block||u.st==='hold';
    for(let k=0;k<T.length;k++){ const p=T[k]; let ox=0, oy=0;
      imp.concat(inc_).forEach(q=>{ const d=Math.hypot(p[0]-q.x,p[1]-q.y); if(d<6.5){ const w=(1-d/6.5)*(1-(G.t-q.t)/3)*(q.k===2?1.6:1.0); ox+=(p[0]-q.x)/(d||1)*w*0.7-fx*w*0.6; oy+=(p[1]-q.y)/(d||1)*w*0.7-fy*w*0.6; } });
      if(line&&(nv||nc)){ let push=0, ex=0, ey=0, en=0; eachNear(p[0],p[1],2.6,(a,j,d)=>{ const rx=a.x-p[0], ry=a.y-p[1]; if(rx*fx+ry*fy<-0.3) return; if(a.arm&&G.groups[a.g].violent&&d>1.2){ ex+=rx; ey+=ry; en++; } else if(d<1.6) push++; }, 1);
        if(push){ const m=Math.min(0.9,push*0.22); ox-=fx*m; oy-=fy*m; } if(en&&reacted){ ox+=ex/en*0.18; oy+=ey/en*0.18; } }
      if(line&&reacted&&nv){ let bd=12, bx=0, by=0; for(const a of VL){ const d=Math.hypot(a.x-p[0],a.y-p[1]); if(d<bd&&(a.x-p[0])*fx+(a.y-p[1])*fy>0){ bd=d; bx=a.x; by=a.y; } } if(bd<12){ const w=(1-bd/12)*0.9; ox+=fx*w+(bx-p[0])/bd*w*0.25; oy+=fy*w+(by-p[1])/bd*w*0.25; } } /* encaran a quien les amenaza */
      const m=Math.hypot(ox,oy); if(m>1.6){ ox*=1.6/m; oy*=1.6/m; } if(free0(p[0]+ox,p[1]+oy)){ p[0]+=ox; p[1]+=oy; } }
    /* heridos: salen de la formación hacia el furgón más cercano (sin sangre: solo un punto que se va con ayuda) */
    if(!u.D){ u.D=T.map(p=>[p[0],p[1],0,0]); }
    while(u.D.length>n){ let bi=u.D.length-1; if(u.lastHit){ let bd=1e9; u.D.forEach((p,k)=>{ const d=Math.hypot(p[0]-u.lastHit[0],p[1]-u.lastHit[1]); if(d<bd){ bd=d; bi=k; } }); } const p=u.D.splice(bi,1)[0]; const v=nearestVan(p[0],p[1]); let tx, ty; if(v){ tx=v.x; ty=v.y; } else { tx=p[0]-fx*25; ty=p[1]-fy*25; const q=snapPt(tx,ty); tx=q[0]; ty=q[1]; } (G.evac=G.evac||[]).push({x:p[0],y:p[1],px:p[0],py:p[1],tx,ty,t0:G.t,f:bfs([ci(tx,ty)],G.bld)}); }
    while(u.D.length<n) u.D.push([u.x,u.y,0,0]);
    /* cada agente va a su sitio: acelera, frena al llegar, no atraviesa edificios */
    const vmax=u.st==='charge'?4.9:3.9;
    for(let k=0;k<u.D.length;k++){ const p=u.D[k], q=T[k]||T[T.length-1]; const dx=q[0]-p[0], dy=q[1]-p[1], d=Math.hypot(dx,dy); let wx=0, wy=0; if(d>0.02){ const sp=Math.min(vmax,d/dt*0.55); wx=dx/d*sp; wy=dy/d*sp; }
      p[2]=p[2]*0.45+wx*0.55; p[3]=p[3]*0.45+wy*0.55; let nx=p[0]+p[2]*dt, ny=p[1]+p[3]*dt;
      if(free0(nx,ny)){ p[0]=nx; p[1]=ny; } else if(free0(nx,p[1])){ p[0]=nx; p[3]*=0.3; } else if(free0(p[0],ny)){ p[1]=ny; p[2]*=0.3; } else { const s=snapPt(p[0],p[1]); const sd=Math.hypot(s[0]-p[0],s[1]-p[1]); if(sd>0.01){ const f=Math.min(1,1.5/sd); p[0]+=(s[0]-p[0])*f; p[1]+=(s[1]-p[1])*f; } p[2]=p[3]=0; } } });
  G.evac=(G.evac||[]).filter(e=>{ const d=Math.hypot(e.tx-e.x,e.ty-e.y); if(d<2.5||G.t-e.t0>40){ e.gone=e.gone||G.t; return G.t-e.gone<2; } let dir=descend(e.f,e.x,e.y); if(!dir||dir.at) dir=unit(e.tx-e.x,e.ty-e.y); const sp=Math.min(1.5,0.4+(G.t-e.t0)*0.5); const nx=e.x+dir.x*sp*dt, ny=e.y+dir.y*sp*dt; if(free0(nx,ny)){ e.x=nx; e.y=ny; } return true; });
  /* furgones: la posición que se ve se acerca a la real con suavidad (aparcar y girar sin saltos) */
  G.vans.forEach(v=>{ if(v.rx==null){ v.rx=v.x; v.ry=v.y; v.ra=v.ang||0; } const dx=v.x-v.rx, dy=v.y-v.ry, d=Math.hypot(dx,dy); const st=Math.min(d,5*dt); if(d>0.001){ v.rx+=dx/d*st; v.ry+=dy/d*st; } let da=(v.ang||0)-v.ra; while(da>Math.PI) da-=2*Math.PI; while(da<-Math.PI) da+=2*Math.PI; if(!v.mv&&Math.abs(da)>Math.PI/2){ da+=da>0?-Math.PI:Math.PI; v.ang=v.ra+da; } v.ra+=Math.max(-1.6*dt,Math.min(1.6*dt,da)); }); }
/* puntería de quien lanza: el error depende de la distancia y del pulso de cada persona (sin dados) */
function aimPt(a,x,y){ a.th=(a.th||0)+1; const d=Math.hypot(x-a.x,y-a.y); const e=d*(0.05+0.11*(1-a.nv)); const an=a.r*6.2832+a.th*2.39996, f=((a.th*0.618034+a.r)%1); return [x+Math.cos(an)*e*f,y+Math.sin(an)*e*f]; }
function dacc(k,p){ G.ac=G.ac||{}; const v=(G.ac[k]==null?0.5:G.ac[k])+p; if(v>=1){ G.ac[k]=v-1; return true; } G.ac[k]=v; return false; }
/* ---------------- bucle ---------------- */
function loop(ts){ RAF=0; if(!G||!/^#\/antidisturbios/.test(location.hash)||!document.getElementById('ad-cv')){ return; }
  const dt=Math.min(0.1,(ts-(LAST||ts))/1000); LAST=ts;
  if(G.phase==='live'&&!G.pause&&!G.pend&&!G.radio&&!G.tut){ G.acc=(G.acc||0)+dt*6*G.spd; let n=0; while(G.acc>=0.5&&n<30&&G.phase==='live'){ G.acc-=0.5; n++; step(0.5); } if(n>=30) G.acc=0; }
  draw(); if(ts-(G.hudT||0)>350&&G.phase==='live'){ G.hudT=ts; const h=document.getElementById('ad-hud'); if(h) h.innerHTML=hudHTML(); const lgE=document.getElementById('ad-log'); if(lgE&&G.logN!==G.log.length+':'+(G.log[0]&&G.log[0].t)){ G.logN=G.log.length+':'+(G.log[0]&&G.log[0].t); lgE.innerHTML=G.log.slice(0,40).map(e=>'<li class="'+e.c+'"><time>'+clock(e.t)+'</time>'+esc(e.txt)+'</li>').join(''); } const dbe=document.querySelector('.ad-dlg'); if(dbe){ const cd=Math.max(0,Math.ceil((G.dlgT||0)-G.t)); const ht=L('Diálogo','Dialogue')+(cd?' <small>'+cd+' s</small>':''); if(dbe.innerHTML!==ht) dbe.innerHTML=ht; } const ut=document.querySelector('.ad-unit .t'); if(ut&&G.sel){ ut.innerHTML='<b>'+G.sel.nm+'</b> · '+(G.sel.van?L('Furgón UIP','UIP van'):(G.sel.n-G.sel.inj)+L(' agentes',' officers')+(G.sel.inj?' · '+G.sel.inj+L(' heridos',' injured'):''))+' · '+ustate(G.sel); } }
  RAF=requestAnimationFrame(loop); }
function step(dt){ snap(); G.t+=dt; if(G.dirty) computeFields(); while(G.events.length&&G.events[0].t<=G.t) doEvent(G.events.shift().k); moveUnits(dt); formUnits(dt); moveAgents(dt); projectiles(); if(Math.floor(G.t)!==Math.floor(G.t-dt)) tick1(); }
function focusCam(){ const c=G.cam; if(!c||c.z>1.05) return; const P=[]; G.units.forEach(u=>P.push([u.x,u.y])); G.groups.forEach(g=>P.push([g.cx,g.cy])); if(G.esc!=='rival') P.push(G.dest); if(P.length<2) return;
  let x0=1e9,y0=1e9,x1=-1e9,y1=-1e9; P.forEach(p=>{ x0=Math.min(x0,p[0]); x1=Math.max(x1,p[0]); y0=Math.min(y0,p[1]); y1=Math.max(y1,p[1]); }); x0-=45; y0-=45; x1+=45; y1+=45;
  const z=Math.max(1,Math.min(2.4,Math.min(c.cw/((x1-x0)*c.s0),c.ch/((y1-y0)*c.s0)))); if(z<1.15) return; c.z=z; c.s=c.s0*z; c.ox=c.cw/2-(x0+x1)/2*c.s; c.oy=c.ch/2-(y0+y1)/2*c.s; clampCam(); }
function kick(){ if(!RAF){ LAST=0; RAF=requestAnimationFrame(loop); } }
/* ---------------- acciones ---------------- */
function startPlan(seed,noAuto){ if(seed!=null) CFG.s=seed; try{ localStorage.setItem('mat_ad_cfg',JSON.stringify(CFG)); }catch(e){} newGame(CFG); gameShell(); planUpdate(); if(FAC()&&!noAuto){ autoDeploy(); G.tool='van'; } render(); kick(); }
/* equipo de diálogo / mediación con los organizadores (Estimación de M.A.T sobre su efecto) */
function dialBtn(){ const cd=Math.max(0,Math.ceil((G.dlgT||0)-G.t)); return '<button type="button" class="ad-btn ad-dlg" data-a="dial"'+(G.phase!=='live'?' disabled':'')+'>'+L('Diálogo','Dialogue')+(cd?' <small>'+cd+' s</small>':'')+'</button>'; }
function dialogo(){ if(!G||G.phase!=='live') return; if(G.t<(G.dlgT||0)){ toast('El equipo de diálogo sigue hablando: espera '+Math.ceil(G.dlgT-G.t)+' s','The dialogue team is still talking: wait '+Math.ceil(G.dlgT-G.t)+' s'); render(); return; }
  const gs=G.groups.filter(g=>(g.n||alive(g))&&g.state!=='leave'); if(!gs.length){ toast('No hay con quién hablar ahora','Nobody to talk to right now'); return; }
  const calm=gs.filter(g=>!g.violent).sort((a,b)=>b.T-a.T); const g=calm[0]||gs.sort((a,b)=>b.T-a.T)[0]; G.dlgT=G.t+90; G.lastAct=G.t; inc('dialogo'); (G.acts=G.acts||[]).push([G.t,'d']); const R=G.R;
  if(!G.dlgInfo){ G.dlgInfo=1; lg(L('El equipo de diálogo (agentes sin equipo antidisturbios, con chaleco identificativo) habla con los organizadores. La ley permite a la autoridad proponer cambios de recorrido, lugar o duración (LO 9/1983, art. 10); los Mossos d’Esquadra tienen un Área de Mediación para protestas. Su efecto en el juego es una Estimación.','The dialogue team (officers without riot gear, in identifying vests) talks to the organisers. The law lets the authority propose changes of route, place or duration (Spanish Organic Law 9/1983, art. 10); the Mossos d’Esquadra have a Mediation Area for protests. Its effect in the game is an estimate.'),''); }
  fxt(g.cx,g.cy,'Diálogo','Dialogue','#bfe3a5');
  if(g.violent){ g.T=Math.max(0,g.T-2); lg(L('Diálogo con ','Dialogue with ')+gArt(g)+L(': con violencia en marcha apenas sirve; primero hay que aislar a los violentos',': with violence going on it barely helps; the violent ones must be isolated first'),'bad'); render(); return; }
  if(g.k==='A'||g.k==='B'){ g.T=Math.max(0,g.T-4); lg(L('Diálogo con ','Dialogue with ')+gArt(g)+L(': escuchan poco, pero bajan algo el tono',': they hardly listen, but tone it down a little'),''); render(); return; }
  if(g.k==='rad'){ let n=0; G.ag.forEach(a=>{ if(a.on&&a.g===g.id&&!a.arm&&a.nv<0.25){ a.lv=1; n++; } }); g.T=Math.max(0,g.T-5); lg(L('Diálogo con ','Dialogue with ')+gArt(g)+L(': unas '+n*10+' personas indecisas se desmarcan y se van; quedan los más duros',': about '+n*10+' undecided people break away and leave; the hard core stays'),'good'); render(); return; }
  g.T=Math.max(0,g.T-12); let n=0; const rad=G.groups.find(q=>q.k==='rad'&&q.host===g&&q.n&&!q.violent); if(rad){ rad.T=Math.max(0,rad.T-3); G.ag.forEach(a=>{ if(a.on&&a.g===rad.id&&!a.arm&&a.nv<0.2){ a.g=g.id; n++; } }); }
  lg(L('Diálogo con los organizadores de ','Dialogue with the organisers of ')+gArt(g)+L(': sus propios voluntarios piden calma y respetar el recorrido',': their own stewards call for calm and to keep to the route')+(n?L(' ('+n*10+' personas del bloque radical vuelven con la marcha)',' ('+n*10+' people from the radical bloc rejoin the march)'):''),'good'); render(); }
function act(a){ if(a==='plan'){ startPlan(); }
  else if(a==='mi-bus'||a==='mi-vis'){ openMission(a.slice(3)); }
  else if(a==='setup'){ G=null; page(setupHTML()); }
  else if(a==='auto') autoDeploy();
  else if(a==='clear'){ G.units=[]; G.vans=[]; G.fences=[]; planUpdate(); render(); }
  else if(a==='start'){ if(!G.units.length) return; G.phase='live'; G.t=0; G.lastAct=0; G.sel=null; G.units.forEach(u=>{ u.home=[u.x,u.y]; }); G.dirty=true; computeFields(); focusCam(); if(FAC()){ let seen=null; try{ seen=localStorage.getItem('mat_ad_tut'); }catch(e){} if(!seen) G.tut=1; } lg(L('Dispositivo desplegado: ','Deployment ready: ')+G.units.length+(FAC()?L(' grupos UIP (',' UIP groups ('):L(' subgrupos (',' sub-groups ('))+G.units.reduce((a,u)=>a+u.n,0)+L(' agentes), ',' officers), ')+G.vans.length+L(' furgones y ',' vans and ')+G.fences.length+L(' vallas',' barriers'),''); render(); kick(); }
  else if(a==='pause'){ G.pause=!G.pause; render(); }
  else if(a==='tut'){ G.tut=1; render(); }
  else if(a==='tutn'){ G.tut=Math.min(4,(G.tut||0)+1); render(); }
  else if(a==='tutx'){ G.tut=0; try{ localStorage.setItem('mat_ad_tut','1'); }catch(e){} render(); }
  else if(a==='dial') dialogo();
  else if(a==='more'){ G.more=!G.more; render(); }
  else if(a==='end'){ if(G.phase==='live'&&G.t<DUR*0.6&&G.groups.some(g=>g.n&&g.state!=='leave')) G.early=G.t; end(); }
  else if(a==='rematch'){ startPlan((Math.random()*4294967296)>>>0); }
  else if(a==='replay'){ const keep={u:G.units.map(u=>[u.home[0],u.home[1]]),v:G.vans.map(v=>[v.x,v.y]),f:G.fences.map(f=>[f.x,f.y])}; startPlan(CFG.s,true); keep.u.forEach(p=>addUnit(p[0],p[1])); keep.v.forEach(p=>addVan(p[0],p[1])); keep.f.forEach(p=>addFence(p[0],p[1])); planUpdate(); render(); }
  else if(a==='share'){ const url=shareURL(); const v=G&&G.v; const txt=L('Antidisturbios en M.A.T: '+(v?v.sc+'/100 en '+G.md.n[0]+'. ':'')+'¿Lo haces mejor?','Riot control on M.A.T: '+(v?v.sc+'/100 in '+G.md.n[1]+'. ':'')+'Can you do better?');
    if(navigator.share){ navigator.share({title:'M.A.T',text:txt,url}).catch(()=>{}); } else if(navigator.clipboard){ navigator.clipboard.writeText(txt+' '+url).then(()=>{ const b=document.querySelector('[data-a="share"]'); if(b) b.textContent=L('Enlace copiado','Link copied'); }).catch(()=>prompt(L('Copia el enlace','Copy the link'),url)); } else prompt(L('Copia el enlace','Copy the link'),url); }
  else if(a==='zin') zoom(1.5); else if(a==='zout') zoom(1/1.5); }
function onClick(e){ const t=e.target.closest('[data-a],[data-set],[data-tool],[data-o],[data-u],[data-fu],[data-spd],[data-r]'); if(!t||!APP.contains(t)||!document.querySelector('.ad')) return;
  if(t.dataset.set){ const k=t.dataset.set; CFG[k]=k==='g'?+t.dataset.v:t.dataset.v; page(setupHTML()); return; }
  if(t.dataset.tool){ G.tool=t.dataset.tool; render(); return; }
  if(t.dataset.r){ if(G&&G.radio) radioChoose(t.dataset.r); return; }
  if(t.dataset.o){ if(G&&G.sel&&G.phase==='live'){ const o=t.dataset.o; if(o==='desel'){ G.sel=null; G.pend=null; render(); } else if(G.sel.van) vorder(G.sel,o); else if(FAC()&&(o==='charge'||o==='smoke')) order(G.sel,o,true); else order(G.sel,o); } return; }
  if(t.dataset.u!=null){ G.sel=G.units[+t.dataset.u]; render(); return; }
  if(t.dataset.fu!=null){ G.sel=G.vans[+t.dataset.fu]; render(); return; }
  if(t.dataset.spd){ G.spd=+t.dataset.spd; G.pause=false; render(); return; }
  act(t.dataset.a); }
let BOUND=false;
/* misiones especiales (escolta del autobús, visita oficial) y Caballería: módulo aparte, se carga al elegirlas */
function openMission(mi,seed){ G=null; if(RAF){ cancelAnimationFrame(RAF); RAF=0; } const v=(document.querySelector('script[data-v]')||{getAttribute:()=>'1'}).getAttribute('data-v');
  page('<p class="sub">'+L('Cargando misión…','Loading mission…')+'</p>');
  import('./antidisturbios_misiones.js?v='+v).then(m=>{ if(!/^#\/antidisturbios/.test(location.hash)) return; m.start({MAPS,page,mi,seed,back:()=>{ G=null; page(setupHTML()); window.scrollTo&&window.scrollTo(0,0); }}); }).catch(()=>page('<p class="sub">'+L('No se pudo cargar la misión. Actualiza la página.','The mission could not be loaded. Reload the page.')+'</p>')); }
export function route(app,x){ APP=app; X=x; const q=(location.hash.split('?')[1]||''); const P={}; q.split('&').forEach(kv=>{ const [k,v]=kv.split('='); if(k) P[k]=decodeURIComponent(v||''); });
  let saved={}; try{ saved=JSON.parse(localStorage.getItem('mat_ad_cfg')||'{}'); }catch(e){}
  CFG={m:MD[P.m]?P.m:(MD[saved.m]?saved.m:'sol'),e:ESC[P.e]?P.e:(ESC[saved.e]?saved.e:'tensa'),h:P.h==='noche'||P.h==='dia'?P.h:(saved.h||'dia'),g:[1,2,4,6].indexOf(+P.g)>=0?+P.g:([1,2,4,6].indexOf(+saved.g)>=0?+saved.g:4),s:P.s?(+P.s>>>0):((Math.random()*4294967296)>>>0),d:P.d==='r'||P.d==='f'?P.d:(saved.d==='r'?'r':'f')};
  if(!document.getElementById('adcss')){ const s=document.createElement('style'); s.id='adcss'; s.textContent=CSS; document.head.appendChild(s); }
  if(!BOUND){ BOUND=true; document.addEventListener('click',onClick); window.addEventListener('resize',()=>{ if(G&&CV&&document.getElementById('ad-cv')){ fit(); draw(); } }); }
  G=null; if(RAF){ cancelAnimationFrame(RAF); RAF=0; }
  const go=()=>{ if(!/^#\/antidisturbios/.test(location.hash)) return; if(P.mi==='bus'||P.mi==='vis') openMission(P.mi,P.s?(+P.s>>>0):null); else if(P.s) startPlan(); else page(setupHTML()); };
  if(MAPS) return go();
  page('<p class="sub">'+L('Cargando calles de Madrid…','Loading Madrid streets…')+'</p>');
  const v=(document.querySelector('script[data-v]')||{getAttribute:()=>'1'}).getAttribute('data-v');
  const get=window.MAT_GET?window.MAT_GET('antidisturbios_mapas.json.gz'):fetch('antidisturbios_mapas.json.gz?v='+v).then(r=>r.json());
  get.then(d=>{ MAPS=d; go(); }).catch(()=>page('<p class="sub">'+L('No se pudieron cargar los mapas. Actualiza la página.','The maps could not be loaded. Reload the page.')+'</p>')); }
if(typeof window!=='undefined') window.MAT_AD_DEBUG=()=>({dotsOf,RV,focusCam,G,CFG,draw,hudHTML,zoom,clampCam,dialogo,slot,addVan,addUnit,addFence,FAC,radioChoose,startPlan,step,verdict,act,order,tap,autoDeploy,tracePath,bfs,ci,across,free0,moveTo,chargeTo,vorder,snapPt,TX,render});
